      "addressLines": ["{{station.address_line_1}}"{{#if station.address_line_2}}, "{{station.address_line_2}}"{{/if}}{{#if station.address_line_3}}, "{{station.address_line_3}}"{{/if}}],
      "countryIsoCode": "{{station.country_iso_code}}",
      "geo": { "latitude": {{station.latitude}}, "longitude": {{station.longitude}} },
      "tzId": "{{station.tz_id}}"
    }{{/arrayJoin}}
  ],
  "offset": {{offset}},
  "pageSize": {{pageSize}}
}
{{/formatJson}}

